import zones from "../../data/reference/result_state_time_zones.json" with { type: "json" };

/** State-level result display clocks, generated by scripts/build-result-state-time-zones.mts. */
export function resultStateTimeZone(stateCode: string): string | null {
  const state = stateCode.toUpperCase();
  return Object.hasOwn(zones, state) ? zones[state as keyof typeof zones] : null;
}
